CREATE TABLE knowledge_proposals (id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE, title TEXT NOT NULL, source_type TEXT NOT NULL CHECK (source_type IN ('project_scan', 'issue', 'comments', 'question', 'stale_refresh', 'project_review')), source_snapshot TEXT NOT NULL DEFAULT '{}', development_context_type TEXT CHECK (development_context_type IS NULL OR development_context_type IN ('branch', 'worktree')), development_branch TEXT, status TEXT NOT NULL CHECK (status IN ('generating', 'ready', 'published', 'rejected', 'failed')), summary TEXT NOT NULL DEFAULT '', error TEXT, creator_type TEXT NOT NULL CHECK (creator_type IN ('user', 'agent')), creator_id TEXT NOT NULL, creator_name TEXT NOT NULL, publisher_type TEXT CHECK (publisher_type IS NULL OR publisher_type IN ('user', 'agent')), publisher_id TEXT, publisher_name TEXT, version INTEGER NOT NULL DEFAULT 1 CHECK (version > 0), created_at TEXT NOT NULL, updated_at TEXT NOT NULL, published_at TEXT);
CREATE INDEX knowledge_proposals_project_status ON knowledge_proposals(project_id, status, updated_at DESC, id);
CREATE TABLE knowledge_proposal_changes (id TEXT PRIMARY KEY, proposal_id TEXT NOT NULL REFERENCES knowledge_proposals(id) ON DELETE CASCADE, target_path TEXT NOT NULL, operation TEXT NOT NULL CHECK (operation IN ('create', 'update', 'delete')), base_digest TEXT, before_content TEXT, after_content TEXT, sort_order INTEGER NOT NULL DEFAULT 0, UNIQUE(proposal_id, target_path));
CREATE INDEX knowledge_proposal_changes_proposal ON knowledge_proposal_changes(proposal_id, sort_order, id);
CREATE TRIGGER knowledge_proposals_revision_insert AFTER INSERT ON knowledge_proposals BEGIN UPDATE global_revision SET revision = revision + 1 WHERE singleton = 1; END;
CREATE TRIGGER knowledge_proposals_revision_update AFTER UPDATE ON knowledge_proposals BEGIN UPDATE global_revision SET revision = revision + 1 WHERE singleton = 1; END;
CREATE TRIGGER knowledge_proposals_revision_delete AFTER DELETE ON knowledge_proposals BEGIN UPDATE global_revision SET revision = revision + 1 WHERE singleton = 1; END;
CREATE TRIGGER knowledge_proposal_changes_revision_insert AFTER INSERT ON knowledge_proposal_changes BEGIN UPDATE global_revision SET revision = revision + 1 WHERE singleton = 1; END;
CREATE TRIGGER knowledge_proposal_changes_revision_update AFTER UPDATE ON knowledge_proposal_changes BEGIN UPDATE global_revision SET revision = revision + 1 WHERE singleton = 1; END;
CREATE TRIGGER knowledge_proposal_changes_revision_delete AFTER DELETE ON knowledge_proposal_changes BEGIN UPDATE global_revision SET revision = revision + 1 WHERE singleton = 1; END;
